    public void setName(java.lang.String name) {
        this.name = name;
    }

    @java.lang.Override
    public java.lang.String toString() {
        return this.getName();
    }
}

/**
 * Simple JavaBean domain object representing an person.
 *
 * @author Ken Krebs
 */
@jakarta.persistence.MappedSuperclass
public class Person extends org.springframework.samples.petclinic.model.BaseEntity {
    @jakarta.persistence.Column(name = "first_name")
    @jakarta.validation.constraints.NotEmpty
    private java.lang.String firstName;

    @jakarta.persistence.Column(name = "last_name")
    @jakarta.validation.constraints.NotEmpty
    private java.lang.String lastName;

    public java.lang.String getFirstName() {
        return this.firstName;
    }

    public void setFirstName(java.lang.String firstName) {
        this.firstName = firstName;
    }

    public java.lang.String getLastName() {
        return this.lastName;
    }

    public void setLastName(java.lang.String lastName) {
        this.lastName = lastName;
    }
}

/**
 *
 * @author Michael Isvy Simple test to make sure that Bean Validation is working (useful
when upgrading to a new version of Hibernate Validator/ Bean Validation)
 */
class ValidatorTests {
    private jakarta.validation.Validator createValidator() {
        org.springframework.validation.beanvalidation.LocalValidatorFactoryBean localValidatorFactoryBean = new org.springframework.validation.beanvalidation.LocalValidatorFactoryBean();
        localValidatorFactoryBean.afterPropertiesSet();
        return localValidatorFactoryBean;
    }

    @org.junit.jupiter.api.Test
    void shouldNotValidateWhenFirstNameEmpty() {
        org.springframework.context.i18n.LocaleContextHolder.setLocale(java.util.Locale.ENGLISH);
        org.springframework.samples.petclinic.model.Person person = new org.springframework.samples.petclinic.model.Person();
        person.setFirstName("");
        person.setLastName("smith");
        jakarta.validation.Validator validator = createValidator();
        java.util.Set<jakarta.validation.ConstraintViolation<org.springframework.samples.petclinic.model.Person>> constraintViolations = validator.validate(person);
        assertThat(constraintViolations).hasSize(1);
        jakarta.validation.ConstraintViolation<org.springframework.samples.petclinic.model.Person> violation = constraintViolations.iterator().next();
        assertThat(violation.getPropertyPath().toString()).isEqualTo("firstName");
        assertThat(violation.getMessage()).isEqualTo("must not be empty");
    }
}

