/**
 * Simple JavaBean domain object representing an owner.
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 * @author Oliver Drotbohm
 */
@jakarta.persistence.Entity
@jakarta.persistence.Table(name = "owners")
public class Owner extends org.springframework.samples.petclinic.model.Person {
    @jakarta.persistence.Column(name = "address")
    @jakarta.validation.constraints.NotEmpty
    private java.lang.String address;

    @jakarta.persistence.Column(name = "city")
    @jakarta.validation.constraints.NotEmpty
    private java.lang.String city;

    @jakarta.persistence.Column(name = "telephone")
    @jakarta.validation.constraints.NotEmpty
    @jakarta.validation.constraints.Digits(fraction = 0, integer = 10)
    private java.lang.String telephone;

    @jakarta.persistence.OneToMany(cascade = jakarta.persistence.CascadeType.ALL, fetch = jakarta.persistence.FetchType.EAGER)
    @jakarta.persistence.JoinColumn(name = "owner_id")
    @jakarta.persistence.OrderBy("name")
    private java.util.List<org.springframework.samples.petclinic.owner.Pet> pets = new java.util.ArrayList<>();

    public java.lang.String getAddress() {
        return this.address;
    }

    public void setAddress(java.lang.String address) {
        this.address = address;
    }

    public java.lang.String getCity() {
        return this.city;
    }

    public void setCity(java.lang.String city) {
        this.city = city;
    }

    public java.lang.String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(java.lang.String telephone) {
        this.telephone = telephone;
    }

    public java.util.List<org.springframework.samples.petclinic.owner.Pet> getPets() {
        return this.pets;
    }

    public void addPet(org.springframework.samples.petclinic.owner.Pet pet) {
        if (pet.isNew()) {
            getPets().add(pet);
        }
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name
     * 		to test
     * @return a pet if pet name is already in use
     */
    public org.springframework.samples.petclinic.owner.Pet getPet(java.lang.String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given id, or null if none found for this Owner.
     *
     * @param name
     * 		to test
     * @return a pet if pet id is already in use
     */
    public org.springframework.samples.petclinic.owner.Pet getPet(java.lang.Integer id) {
        for (org.springframework.samples.petclinic.owner.Pet pet : getPets()) {
            if (!pet.isNew()) {
                java.lang.Integer compId = pet.getId();
                if (compId.equals(id)) {
                    return pet;
                }
            }
        }
        return null;
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name
     * 		to test
     * @return a pet if pet name is already in use
     */
    public org.springframework.samples.petclinic.owner.Pet getPet(java.lang.String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (org.springframework.samples.petclinic.owner.Pet pet : getPets()) {
            if ((!ignoreNew) || (!pet.isNew())) {
                java.lang.String compName = pet.getName();
                compName = (compName == null) ? "" : compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    @java.lang.Override
    public java.lang.String toString() {
        return new org.springframework.core.style.ToStringCreator(this).append("id", this.getId()).append("new", this.isNew()).append("lastName", this.getLastName()).append("firstName", this.getFirstName()).append("address", this.address).append("city", this.city).append("telephone", this.telephone).toString();
    }

    /**
     * Adds the given {@link Visit} to the {@link Pet} with the given identifier.
     *
     * @param petId
     * 		the identifier of the {@link Pet}, must not be {@literal null}.
     * @param visit
     * 		the visit to add, must not be {@literal null}.
     */
    public org.springframework.samples.petclinic.owner.Owner addVisit(java.lang.Integer petId, org.springframework.samples.petclinic.owner.Visit visit) {
        org.springframework.util.Assert.notNull(petId, "Pet identifier must not be null!");
        org.springframework.util.Assert.notNull(visit, "Visit must not be null!");
        org.springframework.samples.petclinic.owner.Pet pet = getPet(petId);
        org.springframework.util.Assert.notNull(pet, "Invalid Pet identifier!");
        pet.addVisit(visit);
        return this;
    }
}

