@org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest(org.springframework.samples.petclinic.owner.OwnerController.class)
class OwnerControllerTests {
    private static final int TEST_OWNER_ID = 1;

    @org.springframework.beans.factory.annotation.Autowired
    private org.springframework.test.web.servlet.MockMvc mockMvc;

    @org.springframework.boot.test.mock.mockito.MockBean
    private org.springframework.samples.petclinic.owner.OwnerRepository owners;

    private org.springframework.samples.petclinic.owner.Owner george() {
        org.springframework.samples.petclinic.owner.Owner george = new org.springframework.samples.petclinic.owner.Owner();
        george.setId(org.springframework.samples.petclinic.owner.OwnerControllerTests.TEST_OWNER_ID);
        george.setFirstName("George");
        george.setLastName("Franklin");
        george.setAddress("110 W. Liberty St.");
        george.setCity("Madison");
        george.setTelephone("6085551023");
        org.springframework.samples.petclinic.owner.Pet max = new org.springframework.samples.petclinic.owner.Pet();
        org.springframework.samples.petclinic.owner.PetType dog = new org.springframework.samples.petclinic.owner.PetType();
        dog.setName("dog");
        max.setType(dog);
        max.setName("Max");
        max.setBirthDate(java.time.LocalDate.now());
        george.addPet(max);
        max.setId(1);
        return george;
    }

    @org.junit.jupiter.api.BeforeEach
    void setup() {
        org.springframework.samples.petclinic.owner.Owner george = george();
        BDDMockito.given(this.owners.findByLastName(ArgumentMatchers.eq("Franklin"), ArgumentMatchers.any(org.springframework.data.domain.Pageable.class))).willReturn(new org.springframework.data.domain.PageImpl<org.springframework.samples.petclinic.owner.Owner>(org.assertj.core.util.Lists.newArrayList(george)));
        BDDMockito.given(this.owners.findAll(ArgumentMatchers.any(org.springframework.data.domain.Pageable.class))).willReturn(new org.springframework.data.domain.PageImpl<org.springframework.samples.petclinic.owner.Owner>(org.assertj.core.util.Lists.newArrayList(george)));
        BDDMockito.given(this.owners.findById(org.springframework.samples.petclinic.owner.OwnerControllerTests.TEST_OWNER_ID)).willReturn(george);
        org.springframework.samples.petclinic.owner.Visit visit = new org.springframework.samples.petclinic.owner.Visit();
