    }

    @org.junit.jupiter.api.Test
    void testShowOwner() throws java.lang.Exception {
        mockMvc.perform(get("/owners/{ownerId}", org.springframework.samples.petclinic.owner.OwnerControllerTests.TEST_OWNER_ID)).andExpect(status().isOk()).andExpect(model().attribute("owner", Matchers.hasProperty("lastName", Matchers.is("Franklin")))).andExpect(model().attribute("owner", Matchers.hasProperty("firstName", Matchers.is("George")))).andExpect(model().attribute("owner", Matchers.hasProperty("address", Matchers.is("110 W. Liberty St.")))).andExpect(model().attribute("owner", Matchers.hasProperty("city", Matchers.is("Madison")))).andExpect(model().attribute("owner", Matchers.hasProperty("telephone", Matchers.is("6085551023")))).andExpect(model().attribute("owner", Matchers.hasProperty("pets", Matchers.not(Matchers.empty())))).andExpect(model().attribute("owner", Matchers.hasProperty("pets", new org.hamcrest.BaseMatcher<java.util.List<org.springframework.samples.petclinic.owner.Pet>>() {
            @java.lang.Override
            public boolean matches(java.lang.Object item) {
                @java.lang.SuppressWarnings("unchecked")
                java.util.List<org.springframework.samples.petclinic.owner.Pet> pets = ((java.util.List<org.springframework.samples.petclinic.owner.Pet>) (item));
                org.springframework.samples.petclinic.owner.Pet pet = pets.get(0);
                if (pet.getVisits().isEmpty()) {
                    return false;
                }
                return true;
            }

            @java.lang.Override
            public void describeTo(org.hamcrest.Description description) {
                description.appendText("Max did not have any visits");
            }
        }))).andExpect(view().name("owners/ownerDetails"));
    }
}

