 * with Spring Data naming conventions so this interface can easily be extended for Spring
 * Data. See:
 * https://docs.spring.io/spring-data/jpa/docs/current/reference/html/#repositories.query-methods.query-creation
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 */
public interface OwnerRepository extends org.springframework.data.repository.Repository<org.springframework.samples.petclinic.owner.Owner, java.lang.Integer> {
    /**
     * Retrieve all {@link PetType}s from the data store.
     *
     * @return a Collection of {@link PetType}s.
     */
    @org.springframework.data.jpa.repository.Query("SELECT ptype FROM PetType ptype ORDER BY ptype.name")
    @org.springframework.transaction.annotation.Transactional(readOnly = true)
    java.util.List<org.springframework.samples.petclinic.owner.PetType> findPetTypes();

    /**
     * Retrieve {@link Owner}s from the data store by last name, returning all owners
     * whose last name <i>starts</i> with the given name.
     *
     * @param lastName
     * 		Value to search for
     * @return a Collection of matching {@link Owner}s (or an empty Collection if none
    found)
     */
    @org.springframework.data.jpa.repository.Query("SELECT DISTINCT owner FROM Owner owner left join  owner.pets WHERE owner.lastName LIKE :lastName% ")
    @org.springframework.transaction.annotation.Transactional(readOnly = true)
    org.springframework.data.domain.Page<org.springframework.samples.petclinic.owner.Owner> findByLastName(@org.springframework.data.repository.query.Param("lastName")
    java.lang.String lastName, org.springframework.data.domain.Pageable pageable);

    /**
     * Retrieve an {@link Owner} from the data store by id.
     *
     * @param id
     * 		the id to search for
     * @return the {@link Owner} if found
     */
    @org.springframework.data.jpa.repository.Query("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id")
    @org.springframework.transaction.annotation.Transactional(readOnly = true)
    org.springframework.samples.petclinic.owner.Owner findById(@org.springframework.data.repository.query.Param("id")
