    @org.junit.jupiter.api.Test
    void testPrint() {
        org.springframework.samples.petclinic.owner.PetType petType = new org.springframework.samples.petclinic.owner.PetType();
        petType.setName("Hamster");
        java.lang.String petTypeName = this.petTypeFormatter.print(petType, java.util.Locale.ENGLISH);
        assertThat(petTypeName).isEqualTo("Hamster");
