 * @author Ken Krebs
 * @author Arjen Poutsma
 * @author Michael Isvy
 * @author Dave Syer
 */
@org.springframework.stereotype.Controller
class VisitController {
    private final org.springframework.samples.petclinic.owner.OwnerRepository owners;

    public VisitController(org.springframework.samples.petclinic.owner.OwnerRepository owners) {
        this.owners = owners;
    }

    @org.springframework.web.bind.annotation.InitBinder
    public void setAllowedFields(org.springframework.web.bind.WebDataBinder dataBinder) {
        dataBinder.setDisallowedFields("id");
    }

    /**
     * Called before each and every @RequestMapping annotated method. 2 goals: - Make sure
     * we always have fresh data - Since we do not use the session scope, make sure that
     * Pet object always has an id (Even though id is not part of the form fields)
     *
     * @param petId
     * @return Pet
     */
    @org.springframework.web.bind.annotation.ModelAttribute("visit")
    public org.springframework.samples.petclinic.owner.Visit loadPetWithVisit(@org.springframework.web.bind.annotation.PathVariable("ownerId")
    int ownerId, @org.springframework.web.bind.annotation.PathVariable("petId")
    int petId, java.util.Map<java.lang.String, java.lang.Object> model) {
        org.springframework.samples.petclinic.owner.Owner owner = this.owners.findById(ownerId);
        org.springframework.samples.petclinic.owner.Pet pet = owner.getPet(petId);
        model.put("pet", pet);
        model.put("owner", owner);
        org.springframework.samples.petclinic.owner.Visit visit = new org.springframework.samples.petclinic.owner.Visit();
        pet.addVisit(visit);
        return visit;
    }

    // Spring MVC calls method loadPetWithVisit(...) before initNewVisitForm is
    // called
    @org.springframework.web.bind.annotation.GetMapping("/owners/{ownerId}/pets/{petId}/visits/new")
    public java.lang.String initNewVisitForm() {
        return "pets/createOrUpdateVisitForm";
    }

    // Spring MVC calls method loadPetWithVisit(...) before processNewVisitForm is
    // called
    @org.springframework.web.bind.annotation.PostMapping("/owners/{ownerId}/pets/{petId}/visits/new")
    public java.lang.String processNewVisitForm(@org.springframework.web.bind.annotation.ModelAttribute
    org.springframework.samples.petclinic.owner.Owner owner, @org.springframework.web.bind.annotation.PathVariable
    int petId, @jakarta.validation.Valid
    org.springframework.samples.petclinic.owner.Visit visit, org.springframework.validation.BindingResult result) {
        if (result.hasErrors()) {
            return "pets/createOrUpdateVisitForm";
        }
        owner.addVisit(petId, visit);
        this.owners.save(owner);
        return "redirect:/owners/{ownerId}";
    }
}

