    org.springframework.data.domain.Pageable pageable;

    @org.junit.jupiter.api.Test
    void shouldFindOwnersByLastName() {
        org.springframework.data.domain.Page<org.springframework.samples.petclinic.owner.Owner> owners = this.owners.findByLastName("Davis", pageable);
