        assertThat(owner.getPets()).hasSize(1);
        assertThat(owner.getPets().get(0).getType()).isNotNull();
        assertThat(owner.getPets().get(0).getType().getName()).isEqualTo("cat");
    }

    @org.junit.jupiter.api.Test
    @org.springframework.transaction.annotation.Transactional
    void shouldInsertOwner() {
        org.springframework.data.domain.Page<org.springframework.samples.petclinic.owner.Owner> owners = this.owners.findByLastName("Schultz", pageable);
        int found = ((int) (owners.getTotalElements()));
        org.springframework.samples.petclinic.owner.Owner owner = new org.springframework.samples.petclinic.owner.Owner();
        owner.setFirstName("Sam");
        owner.setLastName("Schultz");
        owner.setAddress("4, Evans Street");
        owner.setCity("Wollongong");
        owner.setTelephone("4444444444");
        this.owners.save(owner);
        assertThat(owner.getId().longValue()).isNotEqualTo(0);
        owners = this.owners.findByLastName("Schultz", pageable);
        assertThat(owners.getTotalElements()).isEqualTo(found + 1);
    }

    @org.junit.jupiter.api.Test
    @org.springframework.transaction.annotation.Transactional
    void shouldUpdateOwner() {
        org.springframework.samples.petclinic.owner.Owner owner = this.owners.findById(1);
        java.lang.String oldLastName = owner.getLastName();
        java.lang.String newLastName = oldLastName + "X";
        owner.setLastName(newLastName);
        this.owners.save(owner);
        // retrieving new name from database
        owner = this.owners.findById(1);
        assertThat(owner.getLastName()).isEqualTo(newLastName);
    }

    @org.junit.jupiter.api.Test
    void shouldFindAllPetTypes() {
        java.util.Collection<org.springframework.samples.petclinic.owner.PetType> petTypes = this.owners.findPetTypes();
        org.springframework.samples.petclinic.owner.PetType petType1 = org.springframework.samples.petclinic.service.EntityUtils.getById(petTypes, org.springframework.samples.petclinic.owner.PetType.class, 1);
        assertThat(petType1.getName()).isEqualTo("cat");
        org.springframework.samples.petclinic.owner.PetType petType4 = org.springframework.samples.petclinic.service.EntityUtils.getById(petTypes, org.springframework.samples.petclinic.owner.PetType.class, 4);
        assertThat(petType4.getName()).isEqualTo("snake");
    }

    @org.junit.jupiter.api.Test
    @org.springframework.transaction.annotation.Transactional
    void shouldInsertPetIntoDatabaseAndGenerateId() {
        org.springframework.samples.petclinic.owner.Owner owner6 = this.owners.findById(6);
        int found = owner6.getPets().size();
        org.springframework.samples.petclinic.owner.Pet pet = new org.springframework.samples.petclinic.owner.Pet();
        pet.setName("bowser");
        java.util.Collection<org.springframework.samples.petclinic.owner.PetType> types = this.owners.findPetTypes();
        pet.setType(org.springframework.samples.petclinic.service.EntityUtils.getById(types, org.springframework.samples.petclinic.owner.PetType.class, 2));
        pet.setBirthDate(java.time.LocalDate.now());
        owner6.addPet(pet);
        assertThat(owner6.getPets().size()).isEqualTo(found + 1);
        this.owners.save(owner6);
        owner6 = this.owners.findById(6);
        assertThat(owner6.getPets().size()).isEqualTo(found + 1);
        // checks that id has been generated
        pet = owner6.getPet("bowser");
        assertThat(pet.getId()).isNotNull();
    }

    @org.junit.jupiter.api.Test
    @org.springframework.transaction.annotation.Transactional
    void shouldUpdatePetName() throws java.lang.Exception {
        org.springframework.samples.petclinic.owner.Owner owner6 = this.owners.findById(6);
        org.springframework.samples.petclinic.owner.Pet pet7 = owner6.getPet(7);
        java.lang.String oldName = pet7.getName();
        java.lang.String newName = oldName + "X";
        pet7.setName(newName);
        this.owners.save(owner6);
        owner6 = this.owners.findById(6);
        pet7 = owner6.getPet(7);
        assertThat(pet7.getName()).isEqualTo(newName);
    }

    @org.junit.jupiter.api.Test
    void shouldFindVets() {
        java.util.Collection<org.springframework.samples.petclinic.vet.Vet> vets = this.vets.findAll();
        org.springframework.samples.petclinic.vet.Vet vet = org.springframework.samples.petclinic.service.EntityUtils.getById(vets, org.springframework.samples.petclinic.vet.Vet.class, 3);
        assertThat(vet.getLastName()).isEqualTo("Douglas");
        assertThat(vet.getNrOfSpecialties()).isEqualTo(2);
        assertThat(vet.getSpecialties().get(0).getName()).isEqualTo("dentistry");
        assertThat(vet.getSpecialties().get(1).getName()).isEqualTo("surgery");
    }

    @org.junit.jupiter.api.Test
    @org.springframework.transaction.annotation.Transactional
    void shouldAddNewVisitForPet() {
        org.springframework.samples.petclinic.owner.Owner owner6 = this.owners.findById(6);
        org.springframework.samples.petclinic.owner.Pet pet7 = owner6.getPet(7);
        int found = pet7.getVisits().size();
        org.springframework.samples.petclinic.owner.Visit visit = new org.springframework.samples.petclinic.owner.Visit();
        visit.setDescription("test");
        owner6.addVisit(pet7.getId(), visit);
        this.owners.save(owner6);
        owner6 = this.owners.findById(6);
        // 
        // 
        assertThat(pet7.getVisits()).hasSize(found + 1).allMatch(value -> value.getId() != null);
    }

    @org.junit.jupiter.api.Test
    void shouldFindVisitsByPetId() throws java.lang.Exception {
        org.springframework.samples.petclinic.owner.Owner owner6 = this.owners.findById(6);
        org.springframework.samples.petclinic.owner.Pet pet7 = owner6.getPet(7);
        java.util.Collection<org.springframework.samples.petclinic.owner.Visit> visits = pet7.getVisits();
        // 
        // 
        assertThat(visits).hasSize(2).element(0).extracting(org.springframework.samples.petclinic.owner.Visit::getDate).isNotNull();
    }
