/**
 * Utility methods for handling entities. Separate from the BaseEntity class mainly
 * because of dependency on the ORM-associated ObjectRetrievalFailureException.
 *
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @see org.springframework.samples.petclinic.model.BaseEntity
 * @since 29.10.2003
 */
public abstract class EntityUtils {
    /**
     * Look up the entity of the given class with the given id in the given collection.
     *
     * @param entities
     * 		the collection to search
     * @param entityClass
     * 		the entity class to look up
     * @param entityId
     * 		the entity id to look up
     * @return the found entity
     * @throws ObjectRetrievalFailureException
     * 		if the entity was not found
     */
    public static <T extends org.springframework.samples.petclinic.model.BaseEntity> T getById(java.util.Collection<T> entities, java.lang.Class<T> entityClass, int entityId) throws org.springframework.orm.ObjectRetrievalFailureException {
        for (T entity : entities) {
            if ((entity.getId() == entityId) && entityClass.isInstance(entity)) {
                return entity;
            }
        }
        throw new org.springframework.orm.ObjectRetrievalFailureException(entityClass, entityId);
    }
}

/**
 * Cache configuration intended for caches providing the JCache API. This configuration
 * creates the used cache for the application and enables statistics that become
 * accessible via JMX.
 */
@org.springframework.context.annotation.Configuration(proxyBeanMethods = false)
@org.springframework.cache.annotation.EnableCaching
class CacheConfiguration {
    @org.springframework.context.annotation.Bean
    public org.springframework.boot.autoconfigure.cache.JCacheManagerCustomizer petclinicCacheConfigurationCustomizer() {
        return cm -> cm.createCache("vets", cacheConfiguration());
    }

    /**
     * Create a simple configuration that enable statistics via the JCache programmatic
     * configuration API.
     * <p>
     * Within the configuration object that is provided by the JCache API standard, there
     * is only a very limited set of configuration options. The really relevant
     * configuration options (like the size limit) must be set via a configuration
     * mechanism that is provided by the selected JCache implementation.
     */
    private javax.cache.configuration.Configuration<java.lang.Object, java.lang.Object> cacheConfiguration() {
        return new javax.cache.configuration.MutableConfiguration<>().setStatisticsEnabled(true);
    }
}

