 * @author Juergen Hoeller
 * @author Mark Fisher
 * @author Ken Krebs
 * @author Arjen Poutsma
 */
@org.springframework.stereotype.Controller
class VetController {
    private final org.springframework.samples.petclinic.vet.VetRepository vetRepository;

    public VetController(org.springframework.samples.petclinic.vet.VetRepository clinicService) {
        this.vetRepository = clinicService;
    }

    @org.springframework.web.bind.annotation.GetMapping("/vets.html")
    public java.lang.String showVetList(@org.springframework.web.bind.annotation.RequestParam(defaultValue = "1")
    int page, org.springframework.ui.Model model) {
        // Here we are returning an object of type 'Vets' rather than a collection of Vet
        // objects so it is simpler for Object-Xml mapping
        org.springframework.samples.petclinic.vet.Vets vets = new org.springframework.samples.petclinic.vet.Vets();
        org.springframework.data.domain.Page<org.springframework.samples.petclinic.vet.Vet> paginated = findPaginated(page);
        vets.getVetList().addAll(paginated.toList());
        return addPaginationModel(page, paginated, model);
    }

    private java.lang.String addPaginationModel(int page, org.springframework.data.domain.Page<org.springframework.samples.petclinic.vet.Vet> paginated, org.springframework.ui.Model model) {
        java.util.List<org.springframework.samples.petclinic.vet.Vet> listVets = paginated.getContent();
        model.addAttribute("currentPage", page);
        model.addAttribute("totalPages", paginated.getTotalPages());
        model.addAttribute("totalItems", paginated.getTotalElements());
        model.addAttribute("listVets", listVets);
        return "vets/vetList";
    }

    private org.springframework.data.domain.Page<org.springframework.samples.petclinic.vet.Vet> findPaginated(int page) {
        int pageSize = 5;
        org.springframework.data.domain.Pageable pageable = org.springframework.data.domain.PageRequest.of(page - 1, pageSize);
        return vetRepository.findAll(pageable);
    }

    @org.springframework.web.bind.annotation.GetMapping({ "/vets" })
    @org.springframework.web.bind.annotation.ResponseBody
    public org.springframework.samples.petclinic.vet.Vets showResourcesVetList() {
        // Here we are returning an object of type 'Vets' rather than a collection of Vet
        // objects so it is simpler for JSon/Object mapping
        org.springframework.samples.petclinic.vet.Vets vets = new org.springframework.samples.petclinic.vet.Vets();
        vets.getVetList().addAll(this.vetRepository.findAll());
        return vets;
    }
}

